import numpy as np
def load(f):
    lines = open(f).read().split('\n')
    n = int(lines[0].split()[0])
    els, P = [], []
    for l in lines[2:2+n]:
        p = l.split(); els.append(p[0]); P.append([float(x) for x in p[1:4]])
    return els, np.array(P), n
els, P, n = load('opt1.xyz')
bonds = {}
for i in range(n):
    for j in range(i+1,n):
        d = np.linalg.norm(P[i]-P[j])
        cut = 1.75
        if 'H' in (els[i],els[j]): cut = 1.25
        if d < cut:
            bonds.setdefault(i,[]).append(j); bonds.setdefault(j,[]).append(i)
def rings_of(atom, size=6):
    out=[]
    stack=[(atom,[atom])]
    while stack:
        cur,path = stack.pop()
        if len(path)==size:
            if atom in bonds[cur]: out.append(tuple(path))
            continue
        for nb in bonds[cur]:
            if nb in path or nb < atom: continue
            stack.append((nb,path+[nb]))
    return out
allr=set()
for a in range(1,46):
    for r in rings_of(a): allr.add(r)
for r in sorted(allr): print(sorted(r))
